267	static int kws_capture_wait_for_storage(
268	  FAR const struct kws_capture_options_s *options)
269	{
270	  struct stat info;
271	  struct statfs storage;
272	  uint32_t elapsed;
273	  int last_error = -ENODEV;
274	
275	  for (elapsed = 0; elapsed <= KWS_CAPTURE_MOUNT_WAIT_MS;
276	       elapsed += KWS_CAPTURE_MOUNT_POLL_MS)
277	    {
278	      if (stat(options->storage_mountpoint, &info) == 0 &&
279	          statfs(options->storage_mountpoint, &storage) == 0)
280	        {
281	          /*
282	           * R528 may report a mounted FAT volume through either the
283	           * generic FATFS VFS type or the legacy MSDOS type.  Both are
284	           * valid FAT/vfat storage for this capture path.
285	           */
286	          if (storage.f_type != FATFS_SUPER_MAGIC &&
287	              storage.f_type != MSDOS_SUPER_MAGIC)
288	            {
289	              fprintf(stderr,
290	                      "kws capture: %s is not a FAT/vfat mount (type=0x%08lx)\n",
291	                      options->storage_mountpoint,
292	                      (unsigned long)storage.f_type);
293	              return -EINVAL;
294	            }
295	
296	          printf("kws capture: SD mount ready at %s\n",
297	                 options->storage_mountpoint);
298	          return OK;
299	        }
300	
301	      last_error = -errno;
302	      if (elapsed < KWS_CAPTURE_MOUNT_WAIT_MS)
303	        {
304	          usleep(KWS_CAPTURE_MOUNT_POLL_MS * 1000);
305	        }
306	    }
307	
308	  fprintf(stderr,
309	          "kws capture: SD mount %s is not ready after %u ms; "
310	          "insert a FAT32 card and wait for /dev/mmcsd1\n",
311	          options->storage_mountpoint, KWS_CAPTURE_MOUNT_WAIT_MS);
312	  return last_error < 0 ? last_error : -ENODEV;
313	}
