949	int kws_capture_run(FAR const struct kws_capture_options_s *options)
950	{
951	  struct sigaction action;
952	  struct sigaction old_int;
953	  struct sigaction old_term;
954	  char directory[PATH_MAX];
955	  uint16_t completed = 0;
956	  uint16_t take;
957	  int ret;
958	
959	  printf("kws capture: starting label=%s speaker=%s session=%s\n",
960	         options != NULL && options->label != NULL ? options->label : "(null)",
961	         options != NULL && options->speaker_id != NULL ?
962	           options->speaker_id : "(null)",
963	         options != NULL && options->session_id != NULL ?
964	           options->session_id : "(null)");
965	  fflush(stdout);
966	
967	  ret = kws_capture_validate_options(options);
968	  if (ret < 0)
969	    {
970	      fprintf(stderr, "kws capture: invalid options: %d\n", ret);
971	      return ret;
972	    }
973	
974	  ret = kws_capture_wait_for_storage(options);
975	  if (ret < 0)
976	    {
977	      return ret;
978	    }
979	
980	  ret = kws_capture_make_directories(options->output_root);
981	  if (ret < 0)
982	    {
983	      fprintf(stderr, "kws capture: cannot prepare %s: %d\n",
984	              options->output_root, ret);
985	      return ret;
986	    }
987	
988	  if (snprintf(directory, sizeof(directory), "%s/%s", options->output_root,
989	               options->session_id) >= sizeof(directory))
990	    {
991	      return -ENAMETOOLONG;
992	    }
993	
994	  ret = kws_capture_make_directory(directory);
995	  if (ret < 0)
996	    {
997	      fprintf(stderr, "kws capture: cannot prepare %s: %d\n", directory, ret);
998	      return ret;
999	    }
1000	
1001	  ret = kws_capture_check_storage(directory, options->record_ms,
1002	                                  options->count);
1003	  if (ret < 0)
1004	    {
1005	      return ret;
1006	    }
1007	
1008	  take = kws_capture_first_take(options, directory);
1009	  if (take == 0)
1010	    {
1011	      fprintf(stderr, "kws capture: no unused take number in %s\n", directory);
1012	      return -ENOSPC;
1013	    }
1014	
1015	  memset(&action, 0, sizeof(action));
1016	  action.sa_handler = kws_capture_signal_handler;
1017	  sigemptyset(&action.sa_mask);
1018	  g_kws_capture_cancelled = 0;
1019	  sigaction(SIGINT, &action, &old_int);
1020	  sigaction(SIGTERM, &action, &old_term);
1021	
1022	  printf("R528 中文 KWS 语料采集\n");
1023	  printf("label=%s speaker=%s session=%s count=%u record_ms=%lu\n",
1024	         options->label, options->speaker_id, options->session_id,
1025	         options->count, (unsigned long)options->record_ms);
1026	  printf("输出目录：%s\n", directory);
1027	
1028	  while (completed < options->count && !g_kws_capture_cancelled)
1029	    {
1030	      ret = kws_capture_one(options, directory, take);
1031	      if (ret == -EAGAIN)
1032	        {
1033	          continue;
1034	        }
1035	      else if (ret == -EEXIST)
1036	        {
1037	          take++;
1038	          continue;
1039	        }
1040	      else if (ret == -ECANCELED)
1041	        {
1042	          break;
1043	        }
1044	      else if (ret < 0)
1045	        {
1046	          fprintf(stderr, "kws capture: sample %u failed: %d\n", take, ret);
1047	          break;
1048	        }
1049	
1050	      completed++;
1051	      take++;
1052	    }
1053	
1054	  sigaction(SIGINT, &old_int, NULL);
1055	  sigaction(SIGTERM, &old_term, NULL);
1056	  printf("采集结束：已保存 %u/%u 条。\n", completed, options->count);
1057	  if (g_kws_capture_cancelled || ret == -ECANCELED)
1058	    {
1059	      return completed > 0 ? OK : -ECANCELED;
1060	    }
1061	
1062	  return ret < 0 ? ret : OK;
1063	}
