234	                                    strlen(config->password));
235	  if (ret < 0)
236	    {
237	      result->stage = WIFI_MANAGER_STAGE_KEY;
238	      goto out;
239	    }
240	
241	  ret = wapi_set_essid(socket_fd, WIFI_MANAGER_INTERFACE, config->ssid,
242	                       WAPI_ESSID_ON);
243	  if (ret < 0)
244	    {
245	      result->stage = WIFI_MANAGER_STAGE_ESSID;
246	      goto out;
247	    }
248	
249	  ret = -ETIMEDOUT;
250	  result->stage = WIFI_MANAGER_STAGE_ASSOC;
251	  for (retry = 0; retry < WIFI_MANAGER_ASSOC_RETRIES; retry++)
252	    {
253	      if (wifi_manager_ap_connected(socket_fd))
254	        {
255	          ret = OK;
256	          break;
257	        }
258	
259	      sleep(1);
260	    }
261	
262	out:
263	  close(socket_fd);
264	  if (ret < 0)
265	    {
266	      result->error = wifi_manager_normalize_error(ret);
267	      return result->error;
268	    }
269	
270	  return wifi_manager_dhcp(result);
271	}
272	
273	int main(int argc, FAR char *argv[])
274	{
275	  struct wifi_config_s active_config;
276	  struct wifi_config_s pending_config;
277	  struct wifi_connect_result_s result;
278	  enum wifi_config_state_e state = WIFI_CONFIG_STATE_UNKNOWN;
279	  FAR const char *last_failure_stage = NULL;
280	  unsigned int backoff = WIFI_MANAGER_CONFIG_POLL_SEC;
281	  unsigned int retry_wait = 0;
282	  int last_failure = OK;
283	  int socket_fd;
284	  int ret;
285	  bool active_valid = false;
286	  bool associated;
287	
288	  memset(&active_config, 0, sizeof(active_config));
289	  memset(&pending_config, 0, sizeof(pending_config));
290	  syslog(LOG_INFO, "wifi_manager: waiting for Wi-Fi configuration\n");
291	
292	  for (;;)
293	    {
294	      ret = wifi_manager_read_config(&pending_config);
295	      if (ret == -ENOENT)
296	        {
297	          if (state != WIFI_CONFIG_STATE_MISSING)
298	            {
299	              syslog(LOG_INFO,
300	                     "wifi_manager: configuration not present; idle\n");
301	            }
302	
303	          state = WIFI_CONFIG_STATE_MISSING;
304	          wifi_config_clear(&pending_config);
305	          wifi_config_clear(&active_config);
306	          active_valid = false;
307	          retry_wait = 0;
308	          last_failure = OK;
309	          last_failure_stage = NULL;
310	          sleep(WIFI_MANAGER_CONFIG_POLL_SEC);
311	          continue;
312	        }
313	      else if (ret < 0)
314	        {
315	          if (state != WIFI_CONFIG_STATE_INVALID)
316	            {
317	              syslog(LOG_WARNING,
318	                     "wifi_manager: configuration is invalid; idle\n");
319	            }
320	
321	          state = WIFI_CONFIG_STATE_INVALID;
322	          wifi_config_clear(&pending_config);
323	          wifi_config_clear(&active_config);
324	          active_valid = false;
325	          retry_wait = 0;
326	          sleep(WIFI_MANAGER_CONFIG_POLL_SEC);
327	          continue;
328	        }
329	
330	      state = WIFI_CONFIG_STATE_VALID;
331	      if (!active_valid ||
332	          !wifi_config_equal(&pending_config, &active_config))
333	        {
334	          wifi_config_clear(&active_config);
335	          active_config = pending_config;
336	          memset(&pending_config, 0, sizeof(pending_config));
337	          active_valid = true;
338	          backoff = WIFI_MANAGER_CONFIG_POLL_SEC;
339	          retry_wait = 0;
340	          last_failure = OK;
341	          last_failure_stage = NULL;
342	          syslog(LOG_INFO, "wifi_manager: applying new configuration\n");
343	        }
344	      else
345	        {
346	          wifi_config_clear(&pending_config);
347	        }
348	
349	      if (retry_wait > 0)
350	        {
351	          retry_wait = retry_wait > WIFI_MANAGER_CONFIG_POLL_SEC ?
352	                       retry_wait - WIFI_MANAGER_CONFIG_POLL_SEC : 0;
353	          sleep(WIFI_MANAGER_CONFIG_POLL_SEC);
354	          continue;
355	        }
356	
357	      socket_fd = wapi_make_socket();
358	      associated = socket_fd >= 0 &&
359	                   wifi_manager_ap_connected(socket_fd);
360	      if (socket_fd >= 0)
361	        {
362	          close(socket_fd);
363	        }
364	
365	      if (associated && wifi_manager_ipv4_ready())
366	        {
367	          wifi_manager_start_ntp();
368	          backoff = WIFI_MANAGER_CONFIG_POLL_SEC;
369	          last_failure = OK;
370	          last_failure_stage = NULL;
371	          sleep(WIFI_MANAGER_CONFIG_POLL_SEC);
372	          continue;
373	        }
374	
375	      if (associated)
376	        {
377	          ret = wifi_manager_dhcp(&result);
378	        }
379	      else
380	        {
381	          ret = wifi_manager_connect(&active_config, &result);
382	        }
383	
384	      if (ret == 0)
385	        {
386	          backoff = WIFI_MANAGER_CONFIG_POLL_SEC;
387	          last_failure = OK;
388	          last_failure_stage = NULL;
389	          syslog(LOG_INFO, "wifi_manager: connected\n");
390	          if (wifi_manager_ipv4_ready())
391	            {
392	              wifi_manager_start_ntp();
393	            }
394	
395	          sleep(WIFI_MANAGER_CONFIG_POLL_SEC);
396	          continue;
397	        }
398	
399	      if (ret != last_failure || result.stage != last_failure_stage)
400	        {
401	          syslog(LOG_WARNING,
402	                 "wifi_manager: %s failed (%d); retry in %u seconds\n",
403	                 result.stage == NULL ? "connection" : result.stage,
404	                 ret, backoff);
405	          last_failure = ret;
406	          last_failure_stage = result.stage;
407	        }
408	
409	      retry_wait = backoff;
410	      if (backoff < WIFI_MANAGER_BACKOFF_MAX_SEC)
411	        {
412	          backoff *= 2;
413	          if (backoff > WIFI_MANAGER_BACKOFF_MAX_SEC)
414	            {
415	              backoff = WIFI_MANAGER_BACKOFF_MAX_SEC;
416	            }
417	        }
418	    }
419	
420	  return 0;
421	}
