3	 ****************************************************************************/
4	
5	#include <errno.h>
6	#include <stdbool.h>
7	#include <stddef.h>
8	#include <string.h>
9	
10	#include "wifi_config.h"
11	
12	static void wifi_config_wipe(void *buffer, size_t length)
13	{
14	  volatile unsigned char *cursor = buffer;
15	
16	  while (length-- > 0)
17	    {
18	      *cursor++ = 0;
19	    }
20	}
21	
22	static bool wifi_config_control_char(char value)
23	{
24	  unsigned char character = value;
25	
26	  return character < 0x20 || character == 0x7f;
27	}
28	
29	static int wifi_config_decode_value(const char *value, size_t length,
30	                                    char *output, size_t output_size,
31	                                    size_t *decoded_length)
32	{
33	  size_t input_index = 0;
34	  size_t output_index = 0;
35	  bool quoted = false;
36	
37	  while (input_index < length &&
38	         (value[input_index] == ' ' || value[input_index] == '\t'))
39	    {
40	      input_index++;
41	    }
42	
43	  while (length > input_index &&
44	         (value[length - 1] == ' ' || value[length - 1] == '\t'))
45	    {
46	      length--;
47	    }
48	
49	  if (input_index < length && value[input_index] == '"')
50	    {
51	      quoted = true;
52	      input_index++;
53	    }
54	
55	  while (input_index < length)
56	    {
57	      char character = value[input_index++];
58	
59	      if (quoted && character == '"')
60	        {
61	          while (input_index < length &&
62	                 (value[input_index] == ' ' ||
63	                  value[input_index] == '\t'))
64	            {
65	              input_index++;
66	            }
67	
68	          if (input_index != length)
69	            {
70	              return -EINVAL;
71	            }
72	
73	          quoted = false;
74	          break;
75	        }
76	
77	      if (quoted && character == '\\')
78	        {
79	          if (input_index >= length)
80	            {
81	              return -EINVAL;
82	            }
83	
84	          character = value[input_index++];
85	          if (character != '\\' && character != '"')
86	            {
87	              return -EINVAL;
88	            }
89	        }
90	
91	      if (wifi_config_control_char(character) ||
92	          output_index + 1 >= output_size)
93	        {
94	          return -E2BIG;
95	        }
96	
97	      output[output_index++] = character;
98	    }
99	
100	  if (quoted)
101	    {
102	      return -EINVAL;
103	    }
104	
105	  output[output_index] = '\0';
106	  *decoded_length = output_index;
107	  return 0;
108	}
109	
110	static int wifi_config_parse_line(const char *line, size_t length,
111	                                  struct wifi_config_s *candidate,
112	                                  bool *ssid_found,
113	                                  bool *password_found)
114	{
115	  char *destination;
116	  size_t destination_size;
117	  size_t decoded_length;
118	  size_t key_length;
119	  int ret;
120	
121	  while (length > 0 && (*line == ' ' || *line == '\t'))
122	    {
123	      line++;
124	      length--;
125	    }
126	
127	  while (length > 0 &&
128	         (line[length - 1] == ' ' || line[length - 1] == '\t'))
129	    {
130	      length--;
131	    }
132	
133	  if (length == 0 || line[0] == '#')
134	    {
135	      return 0;
136	    }
137	
138	  if (length > 5 && memcmp(line, "SSID=", 5) == 0)
139	    {
140	      if (*ssid_found)
141	        {
142	          return -EINVAL;
143	        }
144	
145	      key_length = 5;
146	      destination = candidate->ssid;
147	      destination_size = sizeof(candidate->ssid);
148	      *ssid_found = true;
149	    }
150	  else if (length > 9 && memcmp(line, "PASSWORD=", 9) == 0)
151	    {
152	      if (*password_found)
153	        {
154	          return -EINVAL;
155	        }
156	
157	      key_length = 9;
158	      destination = candidate->password;
159	      destination_size = sizeof(candidate->password);
160	      *password_found = true;
161	    }
162	  else
163	    {
164	      return -EINVAL;
165	    }
166	
167	  ret = wifi_config_decode_value(line + key_length, length - key_length,
168	                                 destination, destination_size,
169	                                 &decoded_length);
170	  if (ret < 0)
171	    {
172	      return ret;
173	    }
174	
175	  if (destination == candidate->ssid)
176	    {
177	      if (decoded_length == 0 || decoded_length > WIFI_CONFIG_SSID_MAX)
178	        {
179	          return -EINVAL;
180	        }
181	    }
182	  else if (decoded_length < WIFI_CONFIG_PASSWORD_MIN ||
183	           decoded_length > WIFI_CONFIG_PASSWORD_MAX)
184	    {
185	      return -EINVAL;
186	    }
187	
188	  return 0;
189	}
190	
191	int wifi_config_parse(const char *data, size_t length,
192	                      struct wifi_config_s *config)
193	{
194	  struct wifi_config_s candidate;
195	  bool ssid_found = false;
196	  bool password_found = false;
197	  size_t line_start = 0;
198	  size_t index;
199	  int ret = 0;
200	
201	  if (data == NULL || config == NULL || length == 0 ||
202	      length > WIFI_CONFIG_FILE_MAX)
203	    {
204	      return -EINVAL;
205	    }
206	
207	  memset(&candidate, 0, sizeof(candidate));
208	
209	  for (index = 0; index <= length; index++)
210	    {
211	      if (index < length && data[index] == '\0')
212	        {
213	          ret = -EINVAL;
214	          goto out;
215	        }
216	
217	      if (index == length || data[index] == '\n')
218	        {
219	          size_t line_length = index - line_start;
220	
221	          if (line_length > 0 && data[line_start + line_length - 1] == '\r')
222	            {
223	              line_length--;
224	            }
225	
226	          ret = wifi_config_parse_line(data + line_start, line_length,
227	                                       &candidate, &ssid_found,
228	                                       &password_found);
229	          if (ret < 0)
230	            {
231	              goto out;
232	            }
233	
234	          line_start = index + 1;
235	        }
236	    }
237	
238	  if (!ssid_found || !password_found)
239	    {
240	      ret = -EINVAL;
241	      goto out;
242	    }
243	
244	  *config = candidate;
245	  wifi_config_wipe(&candidate, sizeof(candidate));
246	  return 0;
247	
248	out:
249	  wifi_config_wipe(&candidate, sizeof(candidate));
250	  return ret;
251	}
252	
253	void wifi_config_clear(struct wifi_config_s *config)
254	{
255	  if (config != NULL)
256	    {
257	      wifi_config_wipe(config, sizeof(*config));
258	    }
259	}
260	
261	int wifi_config_equal(const struct wifi_config_s *left,
262	                      const struct wifi_config_s *right)
263	{
264	  if (left == NULL || right == NULL)
265	    {
266	      return 0;
267	    }
268	
269	  return strcmp(left->ssid, right->ssid) == 0 &&
270	         strcmp(left->password, right->password) == 0;
271	}
