5	#include <assert.h>
6	#include <stdio.h>
7	#include <string.h>
8	
9	#include "../wifi_config.h"
10	
11	static void expect_valid(const char *text, const char *ssid,
12	                         const char *password)
13	{
14	  struct wifi_config_s config;
15	  int ret;
16	
17	  memset(&config, 0xa5, sizeof(config));
18	  ret = wifi_config_parse(text, strlen(text), &config);
19	  assert(ret == 0);
20	  assert(strcmp(config.ssid, ssid) == 0);
21	  assert(strcmp(config.password, password) == 0);
22	  wifi_config_clear(&config);
23	}
24	
25	static void expect_invalid(const char *text)
26	{
27	  struct wifi_config_s before;
28	  struct wifi_config_s after;
29	  int ret;
30	
31	  memset(&before, 0x5a, sizeof(before));
32	  after = before;
33	  ret = wifi_config_parse(text, strlen(text), &after);
34	  assert(ret < 0);
35	  assert(memcmp(&before, &after, sizeof(before)) == 0);
36	}
37	
38	int main(void)
39	{
40	  char ssid32[33];
41	  char pass63[64];
42	  char boundary[160];
43	
44	  expect_valid("SSID=Home\nPASSWORD=12345678\n",
45	               "Home", "12345678");
46	  expect_valid("SSID=\"My Home\"\r\nPASSWORD=\"pass word\"\r\n",
47	               "My Home", "pass word");
48	  expect_valid("# comment\n\nSSID=\"a;`$()<>\"\n"
49	               "PASSWORD=\"1234;`$()<>5678\"\n",
50	               "a;`$()<>", "1234;`$()<>5678");
51	  expect_valid("SSID=\"a\\\"b\"\nPASSWORD=\"1234\\\\5678\"\n",
52	               "a\"b", "1234\\5678");
53	
54	  memset(ssid32, 's', 32);
55	  ssid32[32] = '\0';
56	  memset(pass63, 'p', 63);
57	  pass63[63] = '\0';
58	  snprintf(boundary, sizeof(boundary), "SSID=%s\nPASSWORD=%s\n",
59	           ssid32, pass63);
60	  expect_valid(boundary, ssid32, pass63);
61	
62	  expect_invalid("SSID=\nPASSWORD=12345678\n");
63	  expect_invalid("SSID=Home\nPASSWORD=short\n");
64	  expect_invalid("SSID=Home\n");
65	  expect_invalid("PASSWORD=12345678\n");
66	  expect_invalid("SSID=A\nSSID=B\nPASSWORD=12345678\n");
67	  expect_invalid("SSID=\"broken\nPASSWORD=12345678\n");
68	  expect_invalid("SSID=Home\nPASSWORD=12345678\nUNKNOWN=value\n");
69	  expect_invalid("SSID=Home\nPASSWORD=12345678\nSSID=Again\n");
70	
71	  puts("wifi_config_test: PASS");
72	  return 0;
73	}
