138	static int routine_parse_uint(const char *text, unsigned int minimum,
139	                              unsigned int maximum, unsigned int *value)
140	{
141	  char *end;
142	  unsigned long parsed;
143	
144	  errno = 0;
145	  parsed = strtoul(text, &end, 10);
146	  if (errno != 0 || *text == '\0' || *end != '\0' ||
147	      parsed < minimum || parsed > maximum)
148	    {
149	      return -EINVAL;
150	    }
151	
152	  *value = parsed;
153	  return 0;
154	}
