73	static void routine_sort_schedule(struct routine_snapshot_s *snapshot)
74	{
75	  struct routine_schedule_item_s item;
76	  uint8_t i;
77	  uint8_t j;
78	
79	  for (i = 1; i < snapshot->schedule_count; i++)
80	    {
81	      item = snapshot->schedule[i];
82	      j = i;
83	      while (j > 0 &&
84	             routine_item_minutes(&snapshot->schedule[j - 1]) >
85	             routine_item_minutes(&item))
86	        {
87	          snapshot->schedule[j] = snapshot->schedule[j - 1];
88	          j--;
89	        }
90	
91	      snapshot->schedule[j] = item;
92	    }
93	}
94	
95	static int routine_find_schedule_id(const struct routine_snapshot_s *snapshot,
96	                                    uint8_t id)
97	{
98	  uint8_t i;
99	
100	  for (i = 0; i < snapshot->schedule_count; i++)
101	    {
102	      if (snapshot->schedule[i].id == id)
103	        {
104	          return i;
105	        }
106	    }
107	
108	  return -ENOENT;
109	}
110	
111	static void routine_reset_schedule(struct routine_snapshot_s *snapshot,
112	                                   int32_t day, bool preserve_carry_over)
113	{
114	  struct routine_schedule_item_s next[ROUTINE_SCHEDULE_MAX];
115	  int index;
116	  uint8_t id;
117	
118	  for (id = 0; id < ROUTINE_SCHEDULE_MAX; id++)
119	    {
120	      index = routine_find_schedule_id(snapshot, id);
121	      if (preserve_carry_over && index >= 0 &&
122	          snapshot->schedule[index].carry_over &&
123	          snapshot->schedule[index].due_day >= day)
124	        {
125	          next[id] = snapshot->schedule[index];
126	        }
127	      else
128	        {
129	          routine_set_default_item(&next[id], id, day);
130	        }
131	    }
132	
133	  memcpy(snapshot->schedule, next, sizeof(next));
134	  snapshot->schedule_count = ROUTINE_SCHEDULE_MAX;
135	  routine_sort_schedule(snapshot);
136	}
