138	static uint8_t routine_find_next_schedule(
139	  const struct routine_snapshot_s *snapshot)
140	{
141	  int64_t now = routine_clock_minutes(snapshot->day, snapshot->hour,
142	                                      snapshot->minute);
143	  uint8_t i;
144	
145	  for (i = 0; i < snapshot->schedule_count; i++)
146	    {
147	      if (!snapshot->schedule[i].completed &&
148	          routine_item_minutes(&snapshot->schedule[i]) >= now)
149	        {
150	          return i;
151	        }
152	    }
153	
154	  return ROUTINE_NO_SCHEDULE;
155	}
