539	static void routine_timer_cb(lv_timer_t *timer)
540	{
541	  struct routine_app_s *app = lv_timer_get_user_data(timer);
542	  struct environment_sample_s environment;
543	  struct routine_clock_s clock;
544	
545	  if (app->model.clock_mode == ROUTINE_CLOCK_DEMO)
546	    {
547	      routine_model_tick_demo(&app->model);
548	    }
549	  else if (routine_get_local_clock(&clock) == OK)
550	    {
551	      time_t wall_time = time(NULL);
552	      int clock_ret;
553	
554	      if (app->last_wall_time != 0 &&
555	          (wall_time < app->last_wall_time ||
556	           wall_time - app->last_wall_time > ROUTINE_CLOCK_REBASE_SECONDS))
557	        {
558	          routine_model_clear_due(&app->model);
559	          routine_model_init_live(&app->model, &clock);
560	          clock_ret = ROUTINE_CLOCK_REBASED;
561	        }
562	      else
563	        {
564	          clock_ret = routine_model_update_clock(&app->model, &clock);
565	        }
566	
567	      app->last_wall_time = wall_time;
568	      if (clock_ret == ROUTINE_CLOCK_REBASED)
569	        {
570	          routine_ui_clear_due();
571	#ifdef CONFIG_ROUTINE_MANAGER_VOICE
572	          if (app->audio_started)
573	            {
574	              audio_service_clear_reminders(&app->audio);
575	            }
576	#endif
577	        }
578	    }
579	  if (app->environment_started &&
580	      environment_service_get_sample(&app->environment, &environment) == 0)
581	    {
582	      routine_model_apply_environment(&app->model, &environment);
583	    }
584	
585	  routine_dispatch_due(app);
586	  routine_ui_update(routine_model_get_snapshot(&app->model));
587	  routine_update_audio_sensors(app);
588	}
