/****************************************************************************
 * contest2026_113_veladuxingke/app/lan_panel/lan_http.c
 ****************************************************************************/

#include <nuttx/config.h>

#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/socket.h>
#include <unistd.h>

#include "lan_http.h"

#define LAN_HTTP_MAX_HEADERS 4096
#define LAN_HTTP_CHUNK 4096

static ssize_t lan_http_read_some(int fd, char *buffer, size_t size)
{
  ssize_t length = recv(fd, buffer, size, 0);
  return length < 0 ? -errno : length;
}

static int lan_http_send_all(int fd, const char *data, size_t length)
{
  while (length > 0)
    {
      ssize_t sent = send(fd, data, length, 0);
      if (sent <= 0)
        {
          return sent == 0 ? -EPIPE : -errno;
        }
      data += sent;
      length -= sent;
    }

  return 0;
}

static char *lan_http_find_header_end(char *data, size_t length)
{
  size_t i;

  for (i = 3; i < length; i++)
    {
      if (data[i - 3] == '\r' && data[i - 2] == '\n' &&
          data[i - 1] == '\r' && data[i] == '\n')
        {
          return data + i + 1;
        }
    }

  return NULL;
}

static int lan_http_header_value(char *headers, const char *name,
                                 char **value)
{
  char *line = headers;
  size_t name_length = strlen(name);

  while (*line != '\0')
    {
      char *end = strstr(line, "\r\n");
      if (end == NULL)
        {
          return -EINVAL;
        }
      *end = '\0';
      if (strncasecmp(line, name, name_length) == 0 &&
          line[name_length] == ':')
        {
          char *cursor = line + name_length + 1;
          while (*cursor == ' ' || *cursor == '\t')
            {
              cursor++;
            }
          *value = cursor;
          return 0;
        }
      line = end + 2;
    }

  return -ENOENT;
}

int lan_http_read_request(int fd, struct lan_http_request_s *request)
{
  char buffer[LAN_HTTP_MAX_HEADERS + 1];
  char *header_end;
  char *line_end;
  char *content_length_text;
  size_t used = 0;
  size_t header_length;
  unsigned long content_length = 0;
  ssize_t length;

  if (request == NULL)
    {
      return -EINVAL;
    }
  memset(request, 0, sizeof(*request));

  while (used < LAN_HTTP_MAX_HEADERS)
    {
      length = lan_http_read_some(fd, buffer + used,
                                  LAN_HTTP_MAX_HEADERS - used);
      if (length <= 0)
        {
          return length == 0 ? -ECONNRESET : (int)length;
        }
      used += length;
      buffer[used] = '\0';
      header_end = lan_http_find_header_end(buffer, used);
      if (header_end != NULL)
        {
          break;
        }
    }

  if (header_end == NULL)
    {
      return -E2BIG;
    }

  line_end = strstr(buffer, "\r\n");
  if (line_end == NULL)
    {
      return -EINVAL;
    }
  *line_end = '\0';
  if (sscanf(buffer, "%7s %255s HTTP/1.%*1[01]", request->method,
             request->path) != 2)
    {
      return -EINVAL;
    }

  header_length = (size_t)(header_end - (line_end + 2));
  (void)header_length;
  *header_end = '\0';
  if (lan_http_header_value(line_end + 2, "Authorization",
                            &content_length_text) == 0)
    {
      strlcpy(request->authorization, content_length_text,
              sizeof(request->authorization));
    }

  content_length_text = NULL;
  if (lan_http_header_value(line_end + 2, "Content-Length",
                            &content_length_text) == 0)
    {
      char *end;
      errno = 0;
      content_length = strtoul(content_length_text, &end, 10);
      if (errno != 0 || *end != '\0' || content_length > sizeof(request->body))
        {
          return -E2BIG;
        }
    }

  if (content_length > 0)
    {
      size_t already = used - (size_t)(header_end - buffer);
      if (already > content_length)
        {
          return -EINVAL;
        }
      if (already > 0)
        {
          memcpy(request->body, header_end, already);
        }
      request->body_length = already;
      while (request->body_length < content_length)
        {
          length = lan_http_read_some(fd,
                                      request->body + request->body_length,
                                      content_length - request->body_length);
          if (length <= 0)
            {
              return length == 0 ? -ECONNRESET : (int)length;
            }
          request->body_length += length;
        }
    }

  return 0;
}

int lan_http_send_response(int fd, int status, const char *type,
                           const char *body, size_t length)
{
  char header[256];
  int header_length;

  header_length = snprintf(header, sizeof(header),
                           "HTTP/1.0 %d\r\nContent-Type: %s\r\nContent-Length: %lu\r\nConnection: close\r\n\r\n",
                           status, type == NULL ? "text/plain" : type,
                           (unsigned long)length);
  if (header_length < 0 || (size_t)header_length >= sizeof(header))
    {
      return -E2BIG;
    }

  if (lan_http_send_all(fd, header, header_length) < 0)
    {
      return -EPIPE;
    }
  return body == NULL || length == 0 ? 0 : lan_http_send_all(fd, body, length);
}

int lan_http_send_file(int fd, const char *path, const char *type)
{
  char buffer[LAN_HTTP_CHUNK];
  struct stat info;
  int file;
  int ret;
  ssize_t length;

  if (stat(path, &info) < 0 || !S_ISREG(info.st_mode))
    {
      return lan_http_send_response(fd, 404, "text/plain", "Not found\n", 10);
    }

  {
    char header[256];
    int header_length = snprintf(header, sizeof(header),
                                 "HTTP/1.0 200\r\nContent-Type: %s\r\nContent-Length: %lu\r\nConnection: close\r\n\r\n",
                                 type == NULL ? "application/octet-stream" : type,
                                 (unsigned long)info.st_size);
    if (header_length < 0 || (size_t)header_length >= sizeof(header))
      {
        return -E2BIG;
      }
    ret = lan_http_send_all(fd, header, header_length);
    if (ret < 0)
      {
        return ret;
      }
  }

  file = open(path, O_RDONLY);
  if (file < 0)
    {
      return -errno;
    }
  do
    {
      length = read(file, buffer, sizeof(buffer));
      if (length > 0)
        {
          ret = lan_http_send_all(fd, buffer, length);
        }
      else
        {
          ret = length < 0 ? -errno : 0;
        }
    }
  while (ret == 0 && length > 0);

  close(file);
  return ret;
}

