#define ROUTINE_STORAGE_EVENTS_PATH    ROUTINE_STORAGE_DIR "/events.log"

struct routine_storage_s
{
  uint64_t generation;
  int32_t last_history_day;
  uint8_t last_history_hour;
  uint8_t last_history_minute;
  time_t schedule_mtime;
  bool history_valid;
};

